************************************************************************

	double precision function P0sumup(CCloop, CCtree)
	implicit none

#include "vars.h"

	double complex CCloop(1), CCtree(1)
	double complex m

	P0sumup = 0

	m = 0
	m = m + CCloop(1)*MatSUN(1,1)
	P0sumup = P0sumup + DBLE(DCONJG(CCtree(1))*m)
	end
